{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Los Angeles RSO allowable rent increase limit","requirement":"Rent for RSO units may be increased only once every 12 months by the allowable rent increase percentage. Since February 2, 2026, the extra utility percentage and the 10% additional-dependent increase are barred; a 10% increase for an added tenant is still allowed.","key_value":"Once every 12 months","coverage_conditions":"RSO rental properties in the City of Los Angeles first built on or before October 1, 1978, plus replacement units under LAMC 151.28: apartments, condos, townhomes, duplexes, two or more single-family units on a parcel, long-term hotel/rooming rooms, ADUs/JADUs, mobile homes.","applicability":{"conditions":[{"type":"built","role":"covered","op":"on_or_before","date":"1978-10-01","basis":"construction"},{"type":"other","text":"Luxury exemption: landlord may apply if monthly rent charged on or before May 31, 1978"}],"per_tenancy":"Condominium and townhome rent amounts are not regulated for tenancies that commenced after December 31, 1995.","coverage_quotes":["Generally, the RSO applies to rental properties that were first built on or before October 1, 1978, as well as replacement units under LAMC Section 151.28","Condominium (Rent amount is not regulated for tenancies that commenced after December 31, 1995)","A landlord can apply for an exemption from the RSO if they can establish the monthly rent charged on or before May 31, 1978,*."]},"exemptions":"Condo and townhome tenancies commencing after December 31, 1995 (rent amount not regulated); luxury exemption on application based on rent charged on or before May 31, 1978; hotel, motel, rooming or boarding rooms occupied 30 or fewer consecutive days.","penalty":null,"effective_date":"2026-02-02","valid_through":null,"citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"Rent may be increased once every 12 months by the allowable rent increase percentage","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles RSO legal reasons for eviction and relocation assistance","requirement":"Under the RSO a landlord may end a tenancy only for listed at-fault causes (nonpayment, lease violation, nuisance, illegal use, and others) or no-fault causes (owner or family move-in, resident manager, demolition, government order, conversion to affordable housing); no-fault evictions require relocation assistance.","key_value":"Notice filed with LAHD within 3 business days of service","coverage_conditions":"All rental units subject to the City of Los Angeles Rent Stabilization Ordinance.","applicability":{"conditions":[{"type":"built","role":"covered","op":"on_or_before","date":"1978-10-01","basis":"construction"},{"type":"other","text":"Luxury exemption: landlord may apply if monthly rent charged on or before May 31, 1978"}],"per_tenancy":null,"coverage_quotes":["Generally, the RSO applies to rental properties that were first built on or before October 1, 1978, as well as replacement units under LAMC Section 151.28"]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"L.A.M.C. §151.09","quoted_span":"All notices to terminate a tenancy for all rental units subject to City’s Rent Stabilization Ordinance (RSO) must be filed with the Los Angeles Housing Department (LAHD) within three (3) business days of service on the tenant per Los Angeles Municipal Code 151.09.C.9 & 165.05.B.5.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","n_rules":2,"note":null}

